import requests

def get_stackoverflow_questions(search_term):
    url = f"https://stackoverflow.com/questions/search?q={search_term}"
    response = requests.get(url)

    if response.status_code == 200:
        return [question["url"] for question in response.json()["questions"]]
    else:
        return []

# Example usage
search_term = "Python"
questions = get_stackoverflow_questions(search_term)

if questions:
    print(f"Top {len(questions)} questions related to '{search_term}':")
    for i, question_url in enumerate(questions[:5], start=1):
        print(f"{i}. {question_url}")
else:
    print("No results found.")
```

This code uses the `requests` library to make an HTTP GET request to the Stack Overflow API and retrieve a list of questions that match the given search term. It then filters out any questions with less than five results and prints them out as a list of URLs.

