    query: 'reviews',
    variables: { id },
  });

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error</p>;

  return (
    <div>
      <h2>{data.reviews[id].title}</h2>
      <p>{data.reviews[id].body}</p>
    </div>
  );
};

export default function Reviews() {
  const reviews = [
    {
      title: 'Event',
      body: 'This event is a great opportunity for everyone to come together and celebrate.',
    },
    {
      title: 'Demo',
      body: 'We have created a demo video to showcase our product.',
    },
    {
      title: 'News',
      body: 'The latest news has been released on our website.',
    },
  ];

  const filteredReviews = reviews.filter((review) =>
    review.title === 'Event' || review.title === 'Demo'
  );

  return (
    <div>
      <h1>Reviews</h1>
      <ul>
        {filteredReviews.map((review) => (
          <Review key={review.id} id={review.id} />
        ))}
      </ul>
    </div>
  );
}
